// Latest returns the newest row for key, tombstone-blind (the raw
// row-level primitive — a deleted key still returns its tombstone
// row; GetLive is the interpreted state-view read). Reads see only
// flushed rows.
func (inst *SysmetricsStore) Latest(ctx context.Context, key uint64) (ent *SysmetricsEntity, found bool, err error) {
	sql := "SELECT * FROM " + SysmetricsTableName +
		" WHERE " + SysmetricsColKey + " = " + factsKeyLiteral(key) +
		" ORDER BY " + SysmetricsColOrder + " DESC LIMIT 1" + factsArrowOutputSettings
	ents, err := inst.queryEntities(ctx, sql)
	if err != nil || len(ents) == 0 {
		return
	}
	ent = ents[0]
	found = true
	return
}

// Replay iterates the rows for key with the order column >= fromOrder
// in ascending order — the event-replay primitive. A zero fromOrder
// replays everything (zero time.Time has no defined UnixNano;
// recordstore.SeqTs(0) is the equivalent explicit bound);
// opts.To bounds the replay exclusively ("state as of To") and
// opts.Limit caps the row count. The sequence is single-use; ctx
// must stay valid until iteration completes; the query may execute
// at call time or lazily during iteration (buffered in v1 — a
// streaming executor changes nothing visible); an error ends the
// sequence as a final (nil, err) pair. Reads see only flushed rows.
func (inst *SysmetricsStore) Replay(ctx context.Context, key uint64, fromOrder time.Time, opts recordstore.ReplayOpts) iter.Seq2[*SysmetricsEntity, error] {
	sql := "SELECT * FROM " + SysmetricsTableName +
		" WHERE " + SysmetricsColKey + " = " + factsKeyLiteral(key)
	if !fromOrder.IsZero() {
		sql += " AND " + SysmetricsColOrder + " >= fromUnixTimestamp64Nano(" + strconv.FormatInt(fromOrder.UnixNano(), 10) + ")"
	}
	if !opts.To.IsZero() {
		sql += " AND " + SysmetricsColOrder + " < fromUnixTimestamp64Nano(" + strconv.FormatInt(opts.To.UnixNano(), 10) + ")"
	}
	sql += " ORDER BY " + SysmetricsColOrder + " ASC"
	if opts.Limit > 0 {
		sql += " LIMIT " + strconv.Itoa(opts.Limit)
	}
	sql += factsArrowOutputSettings
	return inst.iterateEntities(ctx, sql)
}

// --- decode (Arrow → entity bags). ---

// factsSectionReaderI is the uniform slice of the generated read-access
// readers. Column indices stay at their constructor defaults — the
// schema order a SELECT * returns.
type factsSectionReaderI interface {
	LoadFromRecord(raruntime.RecordI) error
	Release()
}

func (inst *SysmetricsStore) queryEntities(ctx context.Context, sql string) (ents []*SysmetricsEntity, err error) {
	for rec, rerr := range inst.exec.QueryArrow(ctx, sql) {
		if rerr != nil {
			err = eh.Errorf("query entities: %w", rerr)
			return
		}
		batch, derr := decodeSysmetricsRecord(rec)
		rec.Release()
		if derr != nil {
			err = derr
			return
		}
		ents = append(ents, batch...)
	}
	return
}

// iterateEntities adapts the buffered query path to the single-use
// iterator contract shared by Replay and the Scan verbs: entities
// yield in query order; an error yields once as (nil, err) and ends
// the sequence.
func (inst *SysmetricsStore) iterateEntities(ctx context.Context, sql string) iter.Seq2[*SysmetricsEntity, error] {
	return func(yield func(*SysmetricsEntity, error) bool) {
		ents, err := inst.queryEntities(ctx, sql)
		if err != nil {
			yield(nil, err)
			return
		}
		for _, ent := range ents {
			if !yield(ent, nil) {
				return
			}
		}
	}
}

// decodeSysmetricsRecord reads one fetched Arrow record into entity bags:
// envelope from the plain readers, components via presence-gated,
// membership-matched reads (fat rows carry optional components — the
// kind-homogeneous helpers cannot decode them).
func decodeSysmetricsRecord(rec arrow.RecordBatch) (ents []*SysmetricsEntity, err error) {
	idR := ra.NewReadAccessFactsPlainEntityIdAttributes()
	tsR := ra.NewReadAccessFactsPlainEntityTimestampAttributes()
	lcR := ra.NewReadAccessFactsPlainEntityLifecycleAttributes()
	symbolR := ra.NewReadAccessFactsTaggedSymbol()
	u8ArrayR := ra.NewReadAccessFactsTaggedU8Array()
	u32ArrayR := ra.NewReadAccessFactsTaggedU32Array()
	f32ArrayR := ra.NewReadAccessFactsTaggedF32Array()
	i32ArrayR := ra.NewReadAccessFactsTaggedI32Array()
	u64ArrayR := ra.NewReadAccessFactsTaggedU64Array()
	boolR := ra.NewReadAccessFactsTaggedBool()
	symbolArrayR := ra.NewReadAccessFactsTaggedSymbolArray()
	i64ArrayR := ra.NewReadAccessFactsTaggedI64Array()
	stringArrayR := ra.NewReadAccessFactsTaggedStringArray()
	u16ArrayR := ra.NewReadAccessFactsTaggedU16Array()
	readers := []factsSectionReaderI{idR, tsR, lcR, symbolR, u8ArrayR, u32ArrayR, f32ArrayR, i32ArrayR, u64ArrayR, boolR, symbolArrayR, i64ArrayR, stringArrayR, u16ArrayR}
	for _, r := range readers {
		err = r.LoadFromRecord(rec)
		if err != nil {
			err = eh.Errorf("load facts reader from record: %w", err)
			return
		}
	}
	defer func() {
		for _, r := range readers {
			r.Release()
		}
	}()

	n := idR.ValueId.Len()
	tsType, ok := tsR.ValueTs.DataType().(*arrow.TimestampType)
	if !ok {
		err = eh.Errorf("order column is not a timestamp (got %s)", tsR.ValueTs.DataType())
		return
	}
	ents = make([]*SysmetricsEntity, 0, n)
	for i := range n {
		ent := &SysmetricsEntity{
			ID: idR.ValueId.Value(i),
			Ts: tsR.ValueTs.Value(i).ToTime(tsType.Unit).UTC(),
		}
		ent.NaturalKey = idR.GetAttrValueNaturalKey(raruntime.EntityIdx(i))
		ent.ExpiresAt = lcR.GetAttrValueExpiresAt(raruntime.EntityIdx(i))
		{
			row, ok, e := sysCpuReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), u8ArrayR.GetAttributes(), u8ArrayR.GetMemberships(), u32ArrayR.GetAttributes(), u32ArrayR.GetMemberships(), f32ArrayR.GetAttributes(), f32ArrayR.GetMemberships(), i32ArrayR.GetAttributes(), i32ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysCpu component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysCpu = option.Some(row)
			}
		}
		{
			row, ok, e := sysCpuInfoReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), i32ArrayR.GetAttributes(), i32ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysCpuInfo component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysCpuInfo = option.Some(row)
			}
		}
		{
			row, ok, e := sysMemReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysMem component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysMem = option.Some(row)
			}
		}
		{
			row, ok, e := sysPsiReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), boolR.GetAttributes(), boolR.GetMemberships(), f32ArrayR.GetAttributes(), f32ArrayR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysPsi component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysPsi = option.Some(row)
			}
		}
		{
			row, ok, e := sysNetReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), symbolArrayR.GetAttributes(), symbolArrayR.GetMemberships(), i32ArrayR.GetAttributes(), i32ArrayR.GetMemberships(), u8ArrayR.GetAttributes(), u8ArrayR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysNet component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysNet = option.Some(row)
			}
		}
		{
			row, ok, e := sysDiskMountReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), symbolArrayR.GetAttributes(), symbolArrayR.GetMemberships(), u8ArrayR.GetAttributes(), u8ArrayR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships(), f32ArrayR.GetAttributes(), f32ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysDiskMount component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysDiskMount = option.Some(row)
			}
		}
		{
			row, ok, e := sysDiskIoReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), symbolArrayR.GetAttributes(), symbolArrayR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships(), u8ArrayR.GetAttributes(), u8ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysDiskIo component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysDiskIo = option.Some(row)
			}
		}
		{
			row, ok, e := sysBatteryReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), symbolArrayR.GetAttributes(), symbolArrayR.GetMemberships(), u8ArrayR.GetAttributes(), u8ArrayR.GetMemberships(), f32ArrayR.GetAttributes(), f32ArrayR.GetMemberships(), i64ArrayR.GetAttributes(), i64ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysBattery component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysBattery = option.Some(row)
			}
		}
		{
			row, ok, e := sysGpuReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), symbolArrayR.GetAttributes(), symbolArrayR.GetMemberships(), i32ArrayR.GetAttributes(), i32ArrayR.GetMemberships(), u8ArrayR.GetAttributes(), u8ArrayR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships(), f32ArrayR.GetAttributes(), f32ArrayR.GetMemberships(), u32ArrayR.GetAttributes(), u32ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysGpu component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysGpu = option.Some(row)
			}
		}
		{
			row, ok, e := sysProcReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), u32ArrayR.GetAttributes(), u32ArrayR.GetMemberships(), symbolArrayR.GetAttributes(), symbolArrayR.GetMemberships(), f32ArrayR.GetAttributes(), f32ArrayR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships(), i32ArrayR.GetAttributes(), i32ArrayR.GetMemberships(), u8ArrayR.GetAttributes(), u8ArrayR.GetMemberships(), i64ArrayR.GetAttributes(), i64ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysProc component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysProc = option.Some(row)
			}
		}
		{
			row, ok, e := sysProcCmdReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), u32ArrayR.GetAttributes(), u32ArrayR.GetMemberships(), stringArrayR.GetAttributes(), stringArrayR.GetMemberships(), symbolArrayR.GetAttributes(), symbolArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysProcCmd component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysProcCmd = option.Some(row)
			}
		}
		{
			row, ok, e := sysSocketReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), symbolArrayR.GetAttributes(), symbolArrayR.GetMemberships(), u16ArrayR.GetAttributes(), u16ArrayR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships(), u32ArrayR.GetAttributes(), u32ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysSocket component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysSocket = option.Some(row)
			}
		}
		{
			row, ok, e := sysTopologyReadRow(i, symbolR.GetAttributes(), symbolR.GetMemberships(), u32ArrayR.GetAttributes(), u32ArrayR.GetMemberships(), i32ArrayR.GetAttributes(), i32ArrayR.GetMemberships(), symbolArrayR.GetAttributes(), symbolArrayR.GetMemberships(), u8ArrayR.GetAttributes(), u8ArrayR.GetMemberships(), u64ArrayR.GetAttributes(), u64ArrayR.GetMemberships())
			if e != nil {
				err = eh.Errorf("read sysTopology component: %w", e)
				return
			}
			if ok {
				row.Id = ent.ID
				row.Ts = ent.Ts
				ent.SysTopology = option.Some(row)
			}
		}
		ents = append(ents, ent)
	}
	return
}
